import { gsap } from "gsap";
import { map, lerp, clamp } from "./utils.js";

export default class MenuItem {
  constructor(el, mousePosition) {
    this.DOM = { el };
    this.mousePosition = mousePosition;
    this.mousePosCache = { ...mousePosition };
    this.direction = { x: 0, y: 0 };
    this.animatableProperties = {
      tx: { previous: 0, current: 0, amt: 0.08 },
      ty: { previous: 0, current: 0, amt: 0.08 },
      rotation: { previous: 0, current: 0, amt: 0.08 },
      brightness: { previous: 1, current: 1, amt: 0.08 },
    };
    this.layout();
    this.initEvents();
  }

  layout() {
    this.DOM.reveal = this.DOM.el.querySelector(".hover-reveal");
    this.DOM.revealInner = this.DOM.reveal.querySelector(".hover-reveal__inner");
    this.DOM.revealImage = this.DOM.reveal.querySelector(".hover-reveal__img");
  }

  calcBounds() {
    this.bounds = {
      el: this.DOM.el.getBoundingClientRect(),
      reveal: this.DOM.reveal.getBoundingClientRect(),
    };
  }

  initEvents() {
    this.mouseenterFn = () => {
      this.showImage();
      this.firstRAFCycle = true;
      this.loopRender();
    };
    this.mouseleaveFn = () => {
      this.stopRendering();
      this.hideImage();
    };

    this.DOM.el.addEventListener("mouseenter", this.mouseenterFn);
    this.DOM.el.addEventListener("mouseleave", this.mouseleaveFn);
  }

  showImage() {
    gsap.killTweensOf(this.DOM.revealInner);
    this.tl = gsap
      .timeline({
        onStart: () => {
          this.DOM.reveal.style.opacity = 1;
          gsap.set(this.DOM.el, { zIndex: 1 });
        },
      })
      .to(this.DOM.revealInner, 0.2, {
        ease: "Sine.easeOut",
        startAt: { x: this.direction.x < 0 ? "100%" : "-100%" },
        x: "0%",
      })
      .to(
        this.DOM.revealImage,
        0.2,
        {
          ease: "Sine.easeOut",
          startAt: { x: this.direction.x < 0 ? "-100%" : "100%" },
          x: "0%",
        },
        0,
      );
  }

  hideImage() {
    gsap.killTweensOf(this.DOM.revealInner);
    gsap.killTweensOf(this.DOM.revealImage);
    this.tl = gsap
      .timeline({
        onStart: () => {
          gsap.set(this.DOM.el, { zIndex: 1 });
        },
        onComplete: () => {
          gsap.set(this.DOM.reveal, { opacity: 0 });
        },
      })
      .to(this.DOM.revealInner, 0.2, {
        ease: "Sine.easeOut",
        x: this.direction.x < 0 ? "-100%" : "100%",
      })
      .to(
        this.DOM.revealImage,
        0.2,
        {
          ease: "Sine.easeOut",
          x: this.direction.x < 0 ? "100%" : "-100%",
        },
        0,
      );
  }

  loopRender() {
    if (!this.requestId) {
      this.requestId = requestAnimationFrame(() => this.render());
    }
  }

  stopRendering() {
    if (this.requestId) {
      window.cancelAnimationFrame(this.requestId);
      this.requestId = undefined;
    }
  }

  render() {
    this.requestId = undefined;
    if (this.firstRAFCycle) {
      this.calcBounds();
    }
    var mouseDistanceX = clamp(
      Math.abs(this.mousePosCache.x - this.mousePosition.x),
      0,
      100,
    );
    this.direction = {
      x: this.mousePosCache.x - this.mousePosition.x,
      y: this.mousePosCache.y - this.mousePosition.y,
    };
    this.mousePosCache = { ...this.mousePosition };
    this.animatableProperties.tx.current = Math.abs(this.mousePosition.x)
      - this.bounds.reveal.width / 2;
    this.animatableProperties.ty.current = Math.abs(this.mousePosition.y)
      - this.bounds.reveal.height;
    this.animatableProperties.rotation.current = this.firstRAFCycle
      ? 0
      : map(mouseDistanceX, 0, 100, 0, this.direction.x < 0 ? -60 : 60);
    this.animatableProperties.brightness.current = this.firstRAFCycle
      ? 1
      : map(mouseDistanceX, 0, 100, 1, 4);
    this.animatableProperties.tx.previous = this.firstRAFCycle
      ? this.animatableProperties.tx.current
      : lerp(
        this.animatableProperties.tx.previous,
        this.animatableProperties.tx.current,
        this.animatableProperties.tx.amt,
      );
    this.animatableProperties.ty.previous = this.firstRAFCycle
      ? this.animatableProperties.ty.current
      : lerp(
        this.animatableProperties.ty.previous,
        this.animatableProperties.ty.current,
        this.animatableProperties.ty.amt,
      );
    this.animatableProperties.rotation.previous = this.firstRAFCycle
      ? this.animatableProperties.rotation.current
      : lerp(
        this.animatableProperties.rotation.previous,
        this.animatableProperties.rotation.current,
        this.animatableProperties.rotation.amt,
      );
    this.animatableProperties.brightness.previous = this.firstRAFCycle
      ? this.animatableProperties.brightness.current
      : lerp(
        this.animatableProperties.brightness.previous,
        this.animatableProperties.brightness.current,
        this.animatableProperties.brightness.amt,
      );
    gsap.set(this.DOM.reveal, {
      x: this.animatableProperties.tx.previous,
      y: this.animatableProperties.ty.previous,
      rotation: this.animatableProperties.rotation.previous,
      filter: `
        brightness(${this.animatableProperties.brightness.previous})
      `,
    });
    this.firstRAFCycle = false;
    this.loopRender();
  }

  destroy() {
    this.stopRendering();
    this.DOM.el.removeEventListener("mouseenter", this.mouseenterFn);
    this.DOM.el.removeEventListener("mouseleave", this.mouseleaveFn);
  }
}
